import { http } from '@buf/googleapis_googleapis.bufbuild_es/google/api/annotations_pb.js';
import type { HttpRule } from '@buf/googleapis_googleapis.bufbuild_es/google/api/http_pb.js';
import {
  OperationSchema,
  operation_info,
} from '@buf/googleapis_googleapis.bufbuild_es/google/longrunning/operations_pb.js';
import { create, type DescMethod, getExtension, hasExtension } from '@bufbuild/protobuf';
import { MethodOptionsSchema } from '@bufbuild/protobuf/wkt';

export type ProtoMethodCategory = 'batch' | 'custom' | 'standard';
export type ProtoMethodExecution = 'long-running' | 'streaming' | 'unary';

export interface ProtoHttpBinding {
  bodyFields: readonly string[];
  method: string;
  path: string;
  pathFields: readonly string[];
  queryFields: readonly string[];
}

export interface ProtoOperationInfo {
  metadataType: string;
  responseType: string;
}

export interface ProtoMethodWorkflow {
  category: ProtoMethodCategory;
  execution: ProtoMethodExecution;
  httpBindings: readonly ProtoHttpBinding[];
  method: DescMethod;
  operation?: ProtoOperationInfo | undefined;
}

const STANDARD_METHOD_PATTERN = /^(Create|Delete|Get|List|Update)[A-Z]/u;
const PATH_FIELD_PATTERN = /\{([^}=]+)(?:=[^}]*)?\}/gu;

function getMethodCategory(name: string): ProtoMethodCategory {
  if (name.startsWith('Batch')) {
    return 'batch';
  }
  return STANDARD_METHOD_PATTERN.test(name) ? 'standard' : 'custom';
}

function getHttpPattern(rule: HttpRule): { method: string; path: string } {
  const { pattern } = rule;
  if (pattern.case === undefined) {
    return { method: '', path: '' };
  }
  if (pattern.case === 'custom') {
    return {
      method: pattern.value.kind.toUpperCase(),
      path: pattern.value.path,
    };
  }
  return {
    method: pattern.case.toUpperCase(),
    path: pattern.value,
  };
}

function parseHttpBinding(method: DescMethod, rule: HttpRule): ProtoHttpBinding {
  const pattern = getHttpPattern(rule);
  const pathFields = Array.from(pattern.path.matchAll(PATH_FIELD_PATTERN), (match) => match[1]).filter(
    (field): field is string => field !== undefined
  );
  const pathFieldSet = new Set(pathFields);
  const requestFields = method.input.fields.map((field) => field.name);
  let bodyFields: string[] = [];
  let queryFields: string[] = [];
  if (rule.body === '*') {
    bodyFields = requestFields.filter((field) => !pathFieldSet.has(field));
  } else if (rule.body) {
    bodyFields = [rule.body];
    queryFields = requestFields.filter((field) => !pathFieldSet.has(field) && field !== rule.body);
  } else {
    queryFields = requestFields.filter((field) => !pathFieldSet.has(field));
  }

  return {
    bodyFields,
    method: pattern.method,
    path: pattern.path,
    pathFields,
    queryFields,
  };
}

export function getProtoMethodWorkflow(method: DescMethod): ProtoMethodWorkflow {
  const options = method.proto.options ?? create(MethodOptionsSchema);
  const httpRule = hasExtension(options, http) ? getExtension(options, http) : undefined;
  const operationInfo = hasExtension(options, operation_info) ? getExtension(options, operation_info) : undefined;
  const streaming = method.methodKind !== 'unary';
  const longRunning = method.output.typeName === OperationSchema.typeName;
  let execution: ProtoMethodExecution = 'unary';
  if (streaming) {
    execution = 'streaming';
  } else if (longRunning) {
    execution = 'long-running';
  }
  const operation =
    operationInfo?.metadataType && operationInfo.responseType
      ? {
          metadataType: operationInfo.metadataType,
          responseType: operationInfo.responseType,
        }
      : undefined;

  return {
    category: getMethodCategory(method.name),
    execution,
    httpBindings: httpRule
      ? [httpRule, ...httpRule.additionalBindings].map((rule) => parseHttpBinding(method, rule))
      : [],
    method,
    operation,
  };
}

import {
  create,
  type DescField,
  type DescMethodUnary,
  type Message,
  type MessageInitShape,
  type MessageShape,
} from '@bufbuild/protobuf';
import type { FieldMask } from '@bufbuild/protobuf/wkt';

import { getProtoMethodWorkflow } from './method-workflow.js';

interface SharedMutationControls {
  requestId?: string | undefined;
  validateOnly?: boolean | undefined;
}

interface RequestInitValues {
  [field: string]: unknown;
}

export interface ComposeCreateRequestOptions extends SharedMutationControls {
  parent?: string | undefined;
  resource: Message;
  resourceId?: string | undefined;
}

export interface ComposeUpdateRequestOptions extends SharedMutationControls {
  resource: Message;
  updateMask?: FieldMask | undefined;
}

export interface ComposeDeleteRequestOptions extends SharedMutationControls {
  etag?: string | undefined;
  name: string;
}

function requireStandardMethod(method: DescMethodUnary, expected: 'Create' | 'Delete' | 'Update'): void {
  const workflow = getProtoMethodWorkflow(method);
  if (workflow.category !== 'standard' || !method.name.startsWith(expected)) {
    throw new TypeError(`Expected ${expected} standard method descriptor, received ${method.name}.`);
  }
}

function findField(method: DescMethodUnary, ...names: string[]): DescField | undefined {
  return method.input.fields.find((field) =>
    names.some((name) => field.localName === name || field.name === name || field.jsonName === name)
  );
}

function requireField(method: DescMethodUnary, purpose: string, ...names: string[]): DescField {
  const field = findField(method, ...names);
  if (!field) {
    throw new TypeError(`${method.name} does not expose an unambiguous ${purpose} field.`);
  }
  return field;
}

function resourceField(method: DescMethodUnary): DescField {
  const workflow = getProtoMethodWorkflow(method);
  const [bodyField] = workflow.httpBindings.flatMap((binding) => binding.bodyFields);
  if (bodyField) {
    return requireField(method, 'resource body', bodyField);
  }
  const candidates = method.input.fields.filter(
    (field) => field.fieldKind === 'message' && field.message.typeName !== 'google.protobuf.FieldMask'
  );
  if (candidates.length !== 1) {
    throw new TypeError(`${method.name} does not expose an unambiguous resource body field.`);
  }
  return candidates[0] as DescField;
}

function assignOptional(
  init: RequestInitValues,
  method: DescMethodUnary,
  value: boolean | FieldMask | string | undefined,
  purpose: string,
  ...names: string[]
): void {
  if (value === undefined) {
    return;
  }
  init[requireField(method, purpose, ...names).localName] = value;
}

function createRequest<Method extends DescMethodUnary>(
  method: Method,
  init: RequestInitValues
): MessageShape<Method['input']> {
  return create<Method['input']>(method.input, init as MessageInitShape<Method['input']>);
}

export function composeCreateRequest<Method extends DescMethodUnary>(
  method: Method,
  options: ComposeCreateRequestOptions
): MessageShape<Method['input']> {
  requireStandardMethod(method, 'Create');
  const resource = resourceField(method);
  const init: RequestInitValues = { [resource.localName]: options.resource };
  assignOptional(init, method, options.parent, 'parent', 'parent');
  assignOptional(init, method, options.resourceId, 'resource id', resource.localName.concat('Id'), 'resourceId');
  assignOptional(init, method, options.requestId, 'request id', 'requestId', 'request_id');
  assignOptional(init, method, options.validateOnly, 'validate only', 'validateOnly', 'validate_only');
  return createRequest(method, init);
}

export function composeUpdateRequest<Method extends DescMethodUnary>(
  method: Method,
  options: ComposeUpdateRequestOptions
): MessageShape<Method['input']> {
  requireStandardMethod(method, 'Update');
  const resource = resourceField(method);
  const init: RequestInitValues = { [resource.localName]: options.resource };
  assignOptional(init, method, options.updateMask, 'update mask', 'updateMask', 'update_mask');
  assignOptional(init, method, options.requestId, 'request id', 'requestId', 'request_id');
  assignOptional(init, method, options.validateOnly, 'validate only', 'validateOnly', 'validate_only');
  return createRequest(method, init);
}

export function composeDeleteRequest<Method extends DescMethodUnary>(
  method: Method,
  options: ComposeDeleteRequestOptions
): MessageShape<Method['input']> {
  requireStandardMethod(method, 'Delete');
  const init: RequestInitValues = {};
  assignOptional(init, method, options.name, 'resource name', 'name');
  assignOptional(init, method, options.etag, 'etag', 'etag');
  assignOptional(init, method, options.requestId, 'request id', 'requestId', 'request_id');
  assignOptional(init, method, options.validateOnly, 'validate only', 'validateOnly', 'validate_only');
  return createRequest(method, init);
}
